#!/usr/bin/env python3
"""
Round 185o (culprits), 5 October 2026. Needs round 184b.

Sharks and rays caught (FAO), under Oceans and Marine meats.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 185o (5 October)\n\nNeeds round 184b (guards on its heading; the mended 184b re-uploaded with it). Tiles patch round185o_tiles.py\nbeside it. No app.js?v= bump.\n\n- Shark finning (asked among the ocean harms): no open source maps finning\n  itself. Added shark_catch: FAO FishStat\'s catch of its own group "Sharks,\n  rays, chimaeras" (CC BY-NC-SA 3.0 IGO), each country shaded by tonnes in the\n  latest year, with ten years before, every species and the fishing areas in\n  the box (tiles fao_fisheries.py now writes fish/fao_sharks.json). Under\n  Oceans > Shark fishing and finning, and Marine meats > Sharks and rays. The\n  note says finned sharks thrown back and unreported catch are not counted.\n- Investor-state cases: isds_unctad.py had never written anything (no isds/\n  folder), so isds_tracker and ect_secrets never drew, and why was unknown.\n  It now tries UNCTAD\'s download links too, checks a file is really excel,\n  writes every page and link tried to isds/build.json, and reads a copy\n  uploaded by hand to isds/download/ first.\n']


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round185o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 184b" not in h.read_text(encoding="utf-8"):
        sys.exit("round185o: round 184b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round185o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html", check=False)
            sys.exit("round185o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round185o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
